const igData = $input.first().json;
const igConvos = igData?.data || [];
const MY_USERNAME = 'kadosh.ai';
const ACCESS_TOKEN = 'IGAAUot1Mq8BxBZAFlFUVIwQU52dnh0cDlWdTJCelNkRjBTQUtNQTFpNGVZAWHIyeWQyb3RfdTAzUGJrNHFYbDRITF9BWEthT05oMmo1ZAWdtLTFQaS1DTzFOcDhkV0ZA1bHlZAcUZA0N29fQkQ2R1BaNmxhdDdmRFdYcThaTkYyOUxDWQZDZD';

const conversations = [];

for (const conv of igConvos) {
    const participants = conv.participants?.data || [];
    const messages = conv.messages?.data || [];

    // Find the customer participant (not our account)
    const customer = participants.find(p => p.username !== MY_USERNAME) || participants[1] || participants[0] || {};
    const myAccount = participants.find(p => p.username === MY_USERNAME) || participants[0] || {};

    // Get the customer's IGSID from their messages (this is the ID needed for sending)
    // Find a message from the customer and get their from.id
    const customerMessage = messages.find(m => m.from?.id !== myAccount.id);
    const customerIGSID = customerMessage?.from?.id || customer.id;

    // Fetch profile picture for customer
    let profilePic = null;
    if (customer.id) {
        try {
            const response = await fetch(`https://graph.instagram.com/v18.0/${customer.id}?fields=profile_pic&access_token=${ACCESS_TOKEN}`);
            const data = await response.json();
            profilePic = data.profile_pic || null;
        } catch (e) {
            // Ignore errors
        }
    }

    const processedMessages = messages.map(m => ({
        id: m.id,
        sender: m.from?.id === myAccount.id ? 'user' : 'lead',
        content: m.message || '',
        timestamp: m.created_time
    })).reverse();

    conversations.push({
        id: conv.id,
        platform: 'instagram',
        participantName: customer.username || 'Customer',
        participantAvatar: profilePic,
        participantId: customerIGSID,
        messages: processedMessages
    });
}

return [{ json: { conversations } }];
